package com.rk.fooddelivery.order.controller;
import com.rk.fooddelivery.auth.CurrentUser; import com.rk.fooddelivery.auth.Role; import com.rk.fooddelivery.order.dto.OrderDtos.*; import com.rk.fooddelivery.order.service.CheckoutService; import jakarta.validation.Valid; import java.util.UUID; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/orders") public class OrderController { private final CheckoutService checkout; private final CurrentUser current; public OrderController(CheckoutService checkout,CurrentUser current){this.checkout=checkout;this.current=current;} @PostMapping public ResponseEntity<OrderResponse> place(@RequestHeader("Idempotency-Key") String key,@Valid @RequestBody CheckoutRequest request){OrderResponse response=checkout.place(current.requireRole(Role.CUSTOMER).id(),key,request);return ResponseEntity.status(HttpStatus.CREATED).header(HttpHeaders.LOCATION,"/api/orders/"+response.id()).body(response);} @GetMapping("/{id}") public OrderResponse get(@PathVariable UUID id){return checkout.get(id);} }
